begin;
select no_plan();
insert into auth.users(id,raw_user_meta_data)
select ('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'{}' from generate_series(31,33) n;
set local request.jwt.claims='{"sub":"00000000-0000-0000-0000-000000000031","role":"authenticated"}';
select lives_ok($$select public.create_household('40000000-0000-0000-0000-000000000001','Onboarding kitchen')$$,'household fixture');
insert into public.household_members(household_id,user_id,role,slot)
values('40000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000032','member',2);
create temp table setup_payloads(personal jsonb,kitchen jsonb);
insert into setup_payloads values(
'{"allergies":[" Peanuts "],"dietaryRequirements":["Vegetarian"],"dislikes":["Mushroom"],"cuisines":[{"cuisine":" Italian ","score":1},{"cuisine":"british","score":0},{"cuisine":"thai","score":-1}],"weights":{"budget":0.5,"variety":0.5,"reuse":0.5,"adventure":0.5,"effort":0.5},"maxCookMinutes":30,"safetyReviewed":true,"completed":false}',
'{"cadence":"weekly","planningDay":0,"timezone":"Pacific/Auckland","defaultServings":1,"equipment":["oven","hob"],"equipmentNote":" Small oven ","completed":false}');
grant select on setup_payloads to authenticated;
set local role authenticated;
select is(public.get_personal_preferences(),null::jsonb,'no personal row until saved');
select is(public.get_kitchen_settings('40000000-0000-0000-0000-000000000001'),null::jsonb,'no shared row until saved');
select lives_ok($$select public.save_personal_preferences((select personal from setup_payloads))$$,'saves personal draft');
select is(public.get_personal_preferences()->'allergies','["peanuts"]'::jsonb,'normalises personal values');
select is((select count(*) from public.dietary_rules)::integer,3,'stores distinct allergy dietary and dislike rows');
select is((select count(distinct rule_type) from public.dietary_rules)::integer,3,'hard constraints remain distinguishable from dislikes');
select is((select sum(score) from public.cuisine_preferences)::integer,0,'positive neutral and negative cuisine signals retained');
select is(public.get_personal_preferences()->'weights'->>'budget','0.5','documented normalized default');
select throws_ok($$select public.save_personal_preferences(jsonb_set((select personal from setup_payloads),'{weights,budget}','2'))$$,'22023','Weight out of range','rejects unnormalised weight');
select throws_ok($$select public.save_personal_preferences((select personal from setup_payloads)||'{"maxCookMinutes":4}'::jsonb)$$,'22023','Invalid personal completion or cooking time','rejects invalid cook time');
select throws_ok($$select public.save_personal_preferences((select personal from setup_payloads)||'{"completed":true,"safetyReviewed":false}'::jsonb)$$,'22023','Invalid personal completion or cooking time','completion requires explicit safety review');
select throws_ok($$select public.save_personal_preferences((select personal from setup_payloads)||'{"allergies":["peanuts"," Peanuts "]}'::jsonb)$$,'22023','Invalid or duplicate preference value','duplicate normalized rules rejected');
select throws_ok($$select public.save_personal_preferences((select personal from setup_payloads)||'{"allergies":["milk"],"cuisines":[{"cuisine":"italian","score":2}]}'::jsonb)$$,'22023','Invalid cuisine preference','invalid late field rejects entire replacement');
select is(public.get_personal_preferences()->'allergies','["peanuts"]'::jsonb,'invalid replacement did not delete existing safety rules');
select lives_ok($$select public.save_personal_preferences((select personal from setup_payloads)||'{"completed":true}'::jsonb)$$,'marks personal completion');
select lives_ok($$select public.save_personal_preferences((select personal from setup_payloads))$$,'stale draft can save valid personal values');
select is(public.get_personal_preferences()->>'completed','true','stale draft does not revoke prior completion');
select throws_ok($$update public.user_preference_profiles set completed=false$$,'42501',null,'direct personal writes cannot bypass aggregate validation');
select throws_ok($$insert into public.dietary_rules values('00000000-0000-0000-0000-000000000031','dislike','milk')$$,'42501',null,'direct rule mutation denied');
select lives_ok($$select public.save_kitchen_settings('40000000-0000-0000-0000-000000000001',(select kitchen from setup_payloads)||'{"completed":true}'::jsonb)$$,'owner saves shared setup');
select is((select timezone from public.households),'Pacific/Auckland','timezone uses canonical household field');
select is((select default_servings from public.households)::integer,1,'servings use canonical household field');
select is(public.get_kitchen_settings('40000000-0000-0000-0000-000000000001')->>'equipmentNote','Small oven','normalises optional note');
select throws_ok($$select public.save_kitchen_settings('40000000-0000-0000-0000-000000000001',(select kitchen from setup_payloads)||'{"cadence":"daily"}'::jsonb)$$,'22023','Invalid kitchen settings','invalid cadence rejected');
select throws_ok($$select public.save_kitchen_settings('40000000-0000-0000-0000-000000000001',(select kitchen from setup_payloads)||'{"timezone":"Invalid/Timezone"}'::jsonb)$$,'22023','Invalid kitchen settings','invalid timezone rejected');
select throws_ok($$select public.save_kitchen_settings('40000000-0000-0000-0000-000000000001',(select kitchen from setup_payloads)||'{"equipment":["oven","jetpack"]}'::jsonb)$$,'22023','Unknown kitchen equipment','unknown equipment rejected');
select is((select count(*) from public.household_equipment)::integer,2,'failed equipment save preserves previous rows');
set local request.jwt.claims='{"sub":"00000000-0000-0000-0000-000000000032","role":"authenticated"}';
select is((select count(*) from public.user_preference_profiles)::integer,0,'second member cannot read first member preference profile');
select is((select count(*) from public.dietary_rules)::integer,0,'second member cannot read private safety rules');
select is(public.get_personal_preferences(),null::jsonb,'personal RPC always uses caller not household owner');
select lives_ok($$select public.save_kitchen_settings('40000000-0000-0000-0000-000000000001',(select kitchen from setup_payloads)||'{"cadence":"fortnightly","planningDay":3,"equipment":["oven","microwave"],"completed":false}'::jsonb)$$,'member edits shared settings');
select is(public.get_kitchen_settings('40000000-0000-0000-0000-000000000001')->>'completed','true','member stale draft does not revoke shared completion');
select throws_ok($$update public.household_planning_settings set cadence='weekly'$$,'42501',null,'client cannot bypass shared atomic settings operation');
set local request.jwt.claims='{"sub":"00000000-0000-0000-0000-000000000031","role":"authenticated"}';
select is(public.get_kitchen_settings('40000000-0000-0000-0000-000000000001')->>'cadence','fortnightly','owner sees member settings');
select is(public.get_kitchen_settings('40000000-0000-0000-0000-000000000001')->'equipment','["microwave","oven"]'::jsonb,'equipment shared and deterministic');
set local request.jwt.claims='{"sub":"00000000-0000-0000-0000-000000000033","role":"authenticated"}';
select is((select count(*) from public.household_planning_settings)::integer,0,'nonmember cannot read shared settings');
select is((select count(*) from public.household_equipment)::integer,0,'nonmember cannot read equipment');
select throws_ok($$select public.get_kitchen_settings('40000000-0000-0000-0000-000000000001')$$,'42501','Household membership required','nonmember RPC read denied');
select throws_ok($$select public.save_kitchen_settings('40000000-0000-0000-0000-000000000001',(select kitchen from setup_payloads))$$,'42501','Household membership required','nonmember RPC write denied');
reset role;
set local request.jwt.claims='{"sub":"00000000-0000-0000-0000-000000000031","role":"authenticated"}';
select public.archive_household('40000000-0000-0000-0000-000000000001');
set local role authenticated;
select throws_ok($$select public.get_kitchen_settings('40000000-0000-0000-0000-000000000001')$$,'42501','Household membership required','archival revokes settings read');
select throws_ok($$select public.save_kitchen_settings('40000000-0000-0000-0000-000000000001',(select kitchen from setup_payloads))$$,'42501','Household membership required','archival revokes settings write');
reset role;
set local role anon;
select throws_ok($$select public.get_personal_preferences()$$,'42501',null,'anonymous personal read denied');
select throws_ok($$select public.save_personal_preferences('{}')$$,'42501',null,'anonymous personal write denied');
reset role;
set constraints all immediate;
select * from finish();
rollback;
